    function RefGridLayout(partner, layout_data, single_center = true) {
        let frist_item_space = layout_data.frist_item_space || 0;
        let h_gap = layout_data.h_gap || 0;
        let v_gap = layout_data.v_gap || 0;
        let column = layout_data.column;
        let row = 0;
        let item_w = layout_data.item_w;
        let item_h = layout_data.item_h;
        let partner_w = partner.width;
        let cell_w = (partner_w / column) - (h_gap / 2);
        let cell_h = item_h;
        let space = (cell_w - item_w) / 2;
        let count = 0;
        let first_item;
        for (let i = 0; i < partner.numChildren; i++) {
            let item = partner.getChildAt(i);
            if (item && item.visible) {
                let index = count % column;
                let first = index == 0 ? 0 : 1;
                let frist_place = index == 0 ? frist_item_space : 0;
                if (index == 0 && count != 0) {
                    row++;
                }
                let x = (cell_w + h_gap) * index + space * first + frist_place;
                let y = (cell_h + v_gap) * row;
                item.pos(x, y);
                count++;
                first_item = item;
            }
        }
        if (single_center && count == 1 && first_item) {
            let x = (partner_w - item_w) / 2;
            let y = 0;
            first_item.pos(x, y);
        }
    }
    window["RefGridLayout"] = RefGridLayout;
    function RefBoxChildsLayout(box, space_x = 0, cell_w = null, is_hide = true, align = "center") {
        let i = 0;
        let box_childs_len = box.numChildren;
        let cont_w = 0;
        switch (align) {
            case "center":
                let num = 0;
                i = 0;
                let all_w = 0;
                let cell;
                for (i = 0; i < box_childs_len; i++) {
                    cell = box.getChildAt(i);
                    if (cell) {
                        if (is_hide && !cell.visible)
                            continue;
                        num++;
                        all_w += cell_w ? cell_w : (cell.contextWidth ? cell.contextWidth : cell.width);
                    }
                }
                all_w += space_x * (num - 1);
                let centerX = (box.width - all_w) / 2;
                let cur_x = centerX;
                for (i = 0; i < box_childs_len; i++) {
                    cell = box.getChildAt(i);
                    if (cell) {
                        if (is_hide && !cell.visible)
                            continue;
                        let w = cell_w ? cell_w : (cell.contextWidth ? cell.contextWidth : cell.width);
                        let acX = cell.anchorX ? cell.anchorX : 0;
                        cell.x = cur_x + (w * acX);
                        cur_x += w + space_x;
                    }
                }
                break;
            case "left":
                cont_w = 0;
                for (i = 0; i < box_childs_len; i++) {
                    let cell = box.getChildAt(i);
                    if (cell) {
                        if (is_hide && !cell.visible)
                            continue;
                        let wid = 0;
                        if (cell_w) {
                            wid = cell_w;
                        }
                        else {
                            wid = cell.contextWidth ? cell.contextWidth : cell.width;
                        }
                        cell.x = cont_w;
                        cont_w += (space_x + wid);
                    }
                }
                break;
            case "right":
                cont_w = 0;
                i = 0;
                cont_w = Math.ceil(box.width);
                for (i = box_childs_len - 1; i >= 0; i--) {
                    let cell = box.getChildAt(i);
                    if (cell) {
                        if (is_hide && !cell.visible)
                            continue;
                        let wid = 0;
                        if (cell_w) {
                            wid = cell_w;
                        }
                        else {
                            wid = cell.contextWidth ? cell.contextWidth : cell.width;
                        }
                        let cell_gap = i == (box_childs_len - 1) ? 0 : space_x;
                        let rx = cont_w - (cell_gap + wid);
                        cell.x = rx;
                        cont_w = rx;
                    }
                }
                break;
        }
    }
    window["RefBoxChildsLayout"] = RefBoxChildsLayout;
    function RefBoxVLayout(box, space_y = 0, filter_hider = false) {
        let cell;
        let sx = 0;
        for (let i = 0; i < box.numChildren; i++) {
            cell = box.getChildAt(i);
            if (filter_hider && !cell.visible)
                continue;
            cell.y = sx;
            sx += cell.height + space_y;
        }
        box.height = sx;
    }
    window["RefBoxVLayout"] = RefBoxVLayout;
