    function OverrideScrollBarChange(list) {
        this.runCallLater(this.changeCells);
        var scrollValue = this._scrollBar.value;
        var lineX = (this._isVertical ? this.repeatX : this.repeatY);
        var lineY = (this._isVertical ? this.repeatY : this.repeatX);
        var scrollLine = Math.floor(scrollValue / this._cellSize);
        if (!this.cacheContent) {
            var index = scrollLine * lineX;
            var num = 0;
            let down = false;
            var toIndex = 0;
            if (index > this._startIndex) {
                num = index - this._startIndex;
                down = true;
                toIndex = this._startIndex + lineX * (lineY + 1);
                this._isMoved = true;
                if (num > 0) {
                    num = num - 1;
                    index = this._startIndex + num;
                }
            }
            else {
                index = index - 1;
                if (index < this._startIndex) {
                    num = this._startIndex - index;
                    down = false;
                    toIndex = this._startIndex - 1;
                    this._isMoved = true;
                }
            }
            for (var i = 0; i < num; i++) {
                if (down) {
                    var cell;
                    cell = this._cells.shift();
                    this._cells[this._cells.length] = cell;
                    var cellIndex = toIndex + i;
                }
                else {
                    cell = this._cells.pop();
                    this._cells.unshift(cell);
                    cellIndex = toIndex - i;
                }
                var pos = Math.floor(cellIndex / lineX) * this._cellSize;
                this._isVertical ? cell.y = pos : cell.x = pos;
                this.renderItem(cell, cellIndex);
            }
            this._startIndex = index;
            this.changeSelectStatus();
        }
        else {
            num = (lineY + 1);
            if (this._createdLine - scrollLine < num) {
                this._createItems(this._createdLine, lineX, this._createdLine + num);
                this.renderItems(this._createdLine * lineX, 0);
                this._createdLine += num;
            }
        }
        var r = this._content._style.scrollRect;
        if (this._isVertical) {
            r.y = scrollValue - this._offset.y;
            r.x = -this._offset.x;
        }
        else {
            r.y = -this._offset.y;
            r.x = scrollValue - this._offset.x;
        }
        this._content.scrollRect = r;
    }
    window["OverrideScrollBarChange"] = OverrideScrollBarChange;
