                for (let key in conf) {
                    let info = conf[key];
                    if (level && level == info.level) {
                        return info;
                    }
                    table.insert(_LVinvestTypeConf, info);
                }
                table.sort(_LVinvestTypeConf, (a, b) => {
                    return a.price < b.price;
                });
                return _LVinvestTypeConf;
