        IsMainRoleCanBeAttack(attacker_vo, not_check_safe_area) {
            let defender_vo = RoleManager.Instance.mainRoleInfo;
            if (attacker_vo == null || defender_vo == null || attacker_vo.hp == 0 || defender_vo.hp == 0) {
                return false;
            }
            if (!not_check_safe_area) {
                if (this.IsSafeArea(null, attacker_vo.pos_x, attacker_vo.pos_y)) {
                    return false;
                }
                else if (defender_vo.safe_area_state == 1 || defender_vo.safe_area_state == 3 || (defender_vo.safe_area_state != 2 && this.IsSafeArea(null, defender_vo.pos_x, defender_vo.pos_y))) {
                    return false;
                }
            }
            let war_group1 = attacker_vo.warGroup;
            let war_group2 = defender_vo.warGroup;
            let same_group = war_group2 == war_group1 && war_group1 > 0;
            if (attacker_vo.vo_type == SceneBaseType.Monster) {
                if (attacker_vo.guild_id > 0 && attacker_vo.guild_id == defender_vo.guild_id) {
                    return false;
                }
                else if (attacker_vo.guild_id > 0 && attacker_vo.guild_id != defender_vo.guild_id) {
                    return true;
                }
                else if (attacker_vo.guaji_flag == 1 || attacker_vo.can_attack == 0
                    || attacker_vo.type == MonsterType.COLLECT || attacker_vo.type == MonsterType.TASK_COLLECT
                    || attacker_vo.type == MonsterType.PICK || attacker_vo.type == MonsterType.NOT_DEAD_COLLECT) {
                    return false;
                }
            }
            if (attacker_vo.vo_type == SceneBaseType.MainRole) {
                return false;
            }
            if (attacker_vo.vo_type != SceneBaseType.Role) {
                return !same_group;
            }
            if (!this.IsPKScene()) {
                return false;
            }
            let canpkByPkStatus = true;
            if (war_group1 == 0 && war_group2 == 0) {
                canpkByPkStatus = this.CanPKByPKStatus(attacker_vo, defender_vo);
            }
            return canpkByPkStatus && !same_group;
        }
        MonsterIsCanBeAttack(defender_vo, same_group, same_guild, guaji_flag, contain_collect_type) {
            if (defender_vo && defender_vo.hp != 0) {
                guaji_flag = guaji_flag == null && true || guaji_flag;
                contain_collect_type = contain_collect_type == null && true || contain_collect_type;
                if (same_group || same_guild) {
                    return false;
                }
                else {
                    let ignore_can_attack = false;
                    if (this.IsEveningScene() && defender_vo.type == MonsterType.COLLECT) {
                        ignore_can_attack = true;
                    }
                    else if (this.IsSeaHegemonyScene() && defender_vo.type == MonsterType.NORMAL) {
                        ignore_can_attack = true;
                    }
                    else if (this.IsFieldScene()
                        && (defender_vo.type == MonsterType.COLLECT
                            || defender_vo.type == MonsterType.TASK_COLLECT
                            || defender_vo.type == MonsterType.PICK
                            || defender_vo.type == MonsterType.NOT_DEAD_COLLECT
                            || defender_vo.type == MonsterType.HAVE_COUNT_NOT_DEAD_COLLECT)) {
                        if (!TaskModel.GetInstance().HaveCollectTask(defender_vo.type_id)) {
                            contain_collect_type = false;
                        }
                    }
                    if ((guaji_flag == true || defender_vo.guaji_flag == guaji_flag)
                        && (defender_vo.can_attack == 1 || ignore_can_attack)
                        && ((defender_vo.type != MonsterType.COLLECT
                            && defender_vo.type != MonsterType.TASK_COLLECT
                            && defender_vo.type != MonsterType.PICK
                            && defender_vo.type != MonsterType.NOT_DEAD_COLLECT
                            && defender_vo.type != MonsterType.HAVE_COUNT_NOT_DEAD_COLLECT) || contain_collect_type)) {
                        return true;
                    }
                }
            }
            return null;
        }
