    class SpecialPackageModelEvent {
    }
    SpecialPackageModelEvent._cname = 'SpecialPackageModelEvent';
    SpecialPackageModelEvent.UPDATE_VIEW = SpecialPackageModelEvent._cname + '.' + 'UPDATE_VIEW';
    class SpecialPackageModel extends EventDispatcher {
        constructor() {
            super();
            this._sepcialPackageViewData = new TMap();
        }
        static GetInstance() {
            if (!SpecialPackageModel._instance) {
                SpecialPackageModel._instance = new SpecialPackageModel();
            }
            return SpecialPackageModel._instance;
        }
        SetSepcialPackageViewData(data) {
            this._sepcialPackageViewData.set(data.base_type + '_' + data.sub_type, data);
        }
        GetSepcialPackageViewData(type) {
            return this._sepcialPackageViewData.get(type);
        }
        SetSepcialPackageTimes(type, times) {
            let info = this._sepcialPackageViewData.get(type);
            if (!info) {
                return;
            }
            info.times = times;
            this._sepcialPackageViewData.set(info.base_type + '_' + info.sub_type, info);
        }
        GetCurLvBuyTimes(list, lv) {
            let tims = list[list.length - 1][1];
            for (const iterator of list) {
                if (iterator[0] == lv) {
                    tims = iterator[1];
                    break;
                }
            }
            return tims;
        }
        GetNextLvBuyTimes(list, lv) {
            let num = 0;
            let vip = 0;
            for (const iterator of list) {
                if (iterator[0] > lv) {
                    num = iterator[1];
                    vip = iterator[0];
                    break;
                }
            }
            if (num > 0) {
                let data = list.find((data, index) => {
                    return data[0] == lv;
                });
                num = num - data[1];
            }
            return { times: num, lv: vip };
        }
        GetCurTimesByDiscount(list, times) {
            for (const iterator of list) {
                if (times < iterator[0]) {
                    return { dis: iterator[1], num: iterator[0] - times };
                }
            }
            return null;
        }
        GetCurTimesByDiscount1(list, times) {
            let dis = 10;
            for (const iterator of list) {
                if (times >= iterator[0]) {
                    dis = iterator[1];
                }
            }
            return dis;
        }
    }
    window['SpecialPackageModel'] = SpecialPackageModel;
    window["SpecialPackageModelEvent"] = SpecialPackageModelEvent;
    SpecialPackageModelEvent["class_name"] = "SpecialPackageModelEvent";
    window["SpecialPackageModel"] = SpecialPackageModel;
    SpecialPackageModel["class_name"] = "SpecialPackageModel";

